"""Freeze V27 hypotheses before fitting or reading new outcome metrics."""
import json,sys,importlib.metadata
import numpy as np
from v27_methods import ROOT,A,ARMS,FINALIST,write
import build_submission as b

def main():
 A.mkdir(parents=True,exist_ok=True); assert not (A/'plan.json').exists()
 old=json.loads((ROOT/'experiments/v26_count_decoder/analysis/plan.json').read_text())
 contexts=old['contexts']
 for ci,c in enumerate(contexts):
  c['null_cases']=[]
  # First null exactly reuses the spent V26 pilot identities; subsequent seeds
  # probe robustness, not independent new studies or new biological reserves.
  n=c['null']; c['null_cases'].append({**n,'calibration_fit':[i for i in n['fit_controls'] if i not in set(n['template'])]})
  for j in [1,2]:
   ids=np.random.default_rng(270270+100*ci+j).permutation(c['left']+c['right']).tolist()
   c['null_cases'].append({'target':'Non-Targeting','seed':270270+100*ci+j,'actual':ids[:400],'reference':ids[400:800],'template':ids[800:1200],'fit_controls':ids[800:],'calibration_fit':ids[1200:]})
  for n in c['null_cases']:
   assert len(n['calibration_fit'])>=200
   sets=[set(n[k]) for k in ['actual','reference','template','calibration_fit']]
   assert all(not sets[i]&sets[j] for i in range(4) for j in range(i))
 deps=list(old['dependencies'])+['v27_methods.py','test_v27_controls.py','train_v27_decoder.py','prepare_v27_experiment.py','run_v27_experiment.py','assess_v27_experiment.py','run_v27_pipeline.py']
 inputs=dict(old['inputs'])
 for n in ['experiments/v26_count_decoder/analysis/plan.json','experiments/v26_count_decoder/analysis/models/H1_conditional.npz','experiments/v26_count_decoder/analysis/models/H1_conditional.json']:
  inputs[n]=b.sha256(ROOT/n)
 write(A/'plan.json',{'version':27,'arms':ARMS,'finalist':FINALIST,'contexts':contexts,'dependencies':{n:b.sha256(ROOT/n) for n in sorted(set(deps))},'inputs':inputs,'raw_guards':old['raw_guards'],'null_policy':old['null_policy'],'mean_contract':old['mean_contract'],'pilot':'Execute sampling-stage ablation, matched H1 panel-output neural fit, three H1 null splits, and all8 H1 treatment cases across all9 arms. Treatment pilot is explicitly diagnostic even when null calibration fails, so every authorized idea receives an intervention test. No adaptive parameter tuning or finalist selection. Expand only if fixed panel_relative passes all H1 calibration/treatment checks.','training':'Same V26 sample selection, source-family exclusions, architecture, epochs and validation-ELBO checkpoint selection. H1 masked model is immutable V26 checkpoint. Panel model changes output mask only, permits shared measured panel genes except directly perturbed output per example. Inputs/state/response bases still exclude panel. Later-family masked and panel fits use same source selection.','arms_description':{'v24':'Original response means and residual10 emitter','v26':'Frozen absolute source-trained masked decoder and sampling/repair','fallback_only':'Frozen masked decoder; lock fallback to V24 counts through restricted depth-stratum repairs. Diagnostic only, not an isolated causal effect of a single arithmetic line.','anchor_only':'Raw query NTC counts, mean transport and integer repairs without extra multinomial measurement draw','calibrated_anchor':'NTC quantile calibration plus anchor transport','relative':'Masked decoder D(z,state,effect)-D(z,state,zero) on raw query NTC shape','calibrated_relative':'Same relative change on independently fitted query-control quantiles','panel_relative':'Same as calibrated_relative, with matched panel-output model','target_shuffled':'Panel-relative model with target descriptors permuted, retaining correct V24 mean response and same random numbers'},'sampling_ablation':'Spent H1 first null: raw counts; second multinomial only; tilted multinomial; depth repair; CPM repair. Last stage must exactly reproduce V26 empirical count digest. Also evaluate mean-transported raw anchor. Intermediate stages need not satisfy protected mean contract; report drift.','calibration':'400 distinct template NTCs and separate fitting NTCs (>=200), disjoint from400 actual and400 reference NTCs. Quantile rank map uses independent tie breaks. Per-cell depth-conditioned joint structure is not guaranteed. Splits are cell-disjoint, not claimed batch/guide-disjoint; archive metadata overlap explicitly. Three null splits reuse biology and are not independent replicates. Finalist must satisfy unchanged V26 envelopes in every split.','treatment':'All same44 historical public cases. At inference only NTCs supply calibration, state and template counts. Full evaluation family excluded from source response means, covariance bases and neural fits. Fixed V24 response means, exact V24 generated gene totals, identical cell libraries; CPM L1 <=0.0005. Correct own-target mean retained, own relative decoder change zeroed.','release':'Only fixed panel_relative eligible. Same raw guards and >=3 primary improvements including DE, worst-family fidelity/reach; improved centered shape Wasserstein; beats anchor_only, calibrated_anchor, calibrated_relative and target_shuffled on >=2 DE metrics each. Every context and all3 null splits must pass. If development passes, lock finalist before completing MD5-verified D3Rest reserve and exclude ALL CD4 information there. No reserve opening or artifact release on failure. Official prep/full-payload/provenance/replay audit required; no automatic upload.','limitations':'H1 pilot and other public biology were used in previous experiments. HCT116 NMAE is unavailable; CD4D1 has200 actual treatment cells. Relative latent draws are not identified counterfactual cells. Null relative descriptors are zero, so response identity by construction is insufficient. Exact mean projection can still distort distribution. Panel fit is a matched mask ablation, not evidence all neural models fail/succeed.'})
 write(A/'runtime.json',{'python':sys.version,'executable':sys.executable,'versions':{n:importlib.metadata.version(n) for n in ['numpy','scipy','pandas','torch','h5py','anndata','scikit-learn','threadpoolctl']},'BLAS_threads':2})
 print('V27 frozen',b.sha256(A/'plan.json'),flush=True)
if __name__=='__main__':main()
